arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_87429a075c054e278ba1bc34100b2ebb.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@if (_submitted)
{
    <div class="alert alert-success mt-4">
        <h3>Application Submitted Successfully!</h3>
        <p>Your application ID is: <strong>@_applicationId</strong></p>
        <p>Thank you for applying. We will review your application and get back to you.</p>
    </div>
}
else
{
    <!-- Step Indicator Bar -->
    <nav class="step-indicator mb-4" aria-label="Application steps">
        <ol class="step-list">
            @for (int i = 0; i < _stepNames.Length; i++)
            {
                var stepIndex = i;
                var stepClass = GetStepClass(stepIndex);
                <li class="step-item @stepClass"
                    @onclick="() => NavigateToStep(stepIndex)"
                    role="button"
                    tabindex="0">
                    <span class="step-number">
                        @if (stepIndex < _currentStep)
                        {
                            <span class="checkmark">✓</span>
                        }
                        else
                        {
                            @(stepIndex + 1)
                        }
                    </span>
                    <span class="step-name">@_stepNames[stepIndex]</span>
                </li>
            }
        </ol>
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    <!-- Step 1: Personal Info -->
    @if (_currentStep == 0)
    {
        <div class="step-content">
            <h2>Personal Information</h2>
            <div class="mb-3">
                <label class="form-label" for="fullName">Full Name *</label>
                <input id="fullName" class="form-control" @bind="_fullName" placeholder="Enter your full name" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="email">Email *</label>
                <input id="email" type="email" class="form-control" @bind="_email" placeholder="Enter your email" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="phone">Phone *</label>
                <input id="phone" type="tel" class="form-control" @bind="_phone" placeholder="Enter your phone number" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="address">Address *</label>
                <textarea id="address" class="form-control" @bind="_address" rows="2" placeholder="Enter your address"></textarea>
            </div>
            <div class="step-buttons">
                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                    @if (_isValidating)
                    {
