@page "/apply"
@rendermode InteractiveServer
@using sv_87429a075c054e278ba1bc34100b2ebb.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@if (_submitted)
{
    <div class="alert alert-success mt-4">
        <h3>Application Submitted Successfully!</h3>
        <p>Your application ID is: <strong>@_applicationId</strong></p>
        <p>Thank you for applying. We will review your application and get back to you.</p>
    </div>
}
else
{
    <!-- Step Indicator Bar -->
    <nav class="step-indicator mb-4" aria-label="Application steps">
        <ol class="step-list">
            @for (int i = 0; i < _stepNames.Length; i++)
            {
                var stepIndex = i;
                var stepClass = GetStepClass(stepIndex);
                <li class="step-item @stepClass"
                    @onclick="() => NavigateToStep(stepIndex)"
                    role="button"
                    tabindex="0">
                    <span class="step-number">
                        @if (stepIndex < _currentStep)
                        {
                            <span class="checkmark">✓</span>
                        }
                        else
                        {
                            @(stepIndex + 1)
                        }
                    </span>
                    <span class="step-name">@_stepNames[stepIndex]</span>
                </li>
            }
        </ol>
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    <!-- Step 1: Personal Info -->
    @if (_currentStep == 0)
    {
        <div class="step-content">
            <h2>Personal Information</h2>
            <div class="mb-3">
                <label class="form-label" for="fullName">Full Name *</label>
                <input id="fullName" class="form-control" @bind="_fullName" placeholder="Enter your full name" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="email">Email *</label>
                <input id="email" type="email" class="form-control" @bind="_email" placeholder="Enter your email" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="phone">Phone *</label>
                <input id="phone" type="tel" class="form-control" @bind="_phone" placeholder="Enter your phone number" />
            </div>
            <div class="mb-3">
                <label class="form-label" for="address">Address *</label>
                <textarea id="address" class="form-control" @bind="_address" rows="2" placeholder="Enter your address"></textarea>
            </div>
            <div class="step-buttons">
                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                    @if (_isValidating)
                    {
                        <span>Validating...</span>
                    }
                    else
                    {
                        <span>Next</span>
                    }
                </button>
            </div>
        </div>
    }

    <!-- Step 2: Work History -->
    @if (_currentStep == 1)
    {
        <div class="step-content">
            <h2>Work History</h2>
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var index = i;
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Position @(index + 1)</h5>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Company Name *</label>
                            <input class="form-control" @bind="_workEntries[index].Company" placeholder="Company name" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Job Title *</label>
                            <input class="form-control" @bind="_workEntries[index].Title" placeholder="Job title" />
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Start Date *</label>
                                <input type="date" class="form-control" @bind="_workEntries[index].StartDate" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" @bind="_workEntries[index].EndDate"
                                       disabled="@_workEntries[index].IsCurrent" />
                                <div class="form-check mt-1">
                                    <input class="form-check-input" type="checkbox" id="current-@index"
                                           @bind="_workEntries[index].IsCurrent" />
                                    <label class="form-check-label" for="current-@index">Currently working here</label>
                                </div>
                            </div>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Description *</label>
                            <textarea class="form-control" @bind="_workEntries[index].Description" rows="3"
                                      placeholder="Describe your responsibilities and achievements"></textarea>
                        </div>
                    </div>
                </div>
            }
            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
            </div>
        </div>
    }

    <!-- Step 3: References -->
    @if (_currentStep == 2)
    {
        <div class="step-content">
            <h2>References</h2>
            @for (int i = 0; i < _references.Count; i++)
            {
                var index = i;
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Reference @(index + 1)</h5>
                            @if (_references.Count > 2)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Name *</label>
                            <input class="form-control" @bind="_references[index].Name" placeholder="Reference name" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Relationship *</label>
                            <input class="form-control" @bind="_references[index].Relationship" placeholder="e.g., Former Manager" />
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Email *</label>
                                <input type="email" class="form-control" @bind="_references[index].Email" placeholder="Email" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Phone *</label>
                                <input type="tel" class="form-control" @bind="_references[index].Phone" placeholder="Phone" />
                            </div>
                        </div>
                    </div>
                </div>
            }
            @if (_references.Count < 3)
            {
                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
            </div>
        </div>
    }

    <!-- Step 4: Cover Letter -->
    @if (_currentStep == 3)
    {
        <div class="step-content">
            <h2>Cover Letter</h2>
            <div class="mb-3">
                <label class="form-label" for="coverLetter">Write your cover letter *</label>
                <textarea id="coverLetter" class="form-control" @bind="_coverLetter" @bind:event="oninput"
                          rows="12" maxlength="2000" placeholder="Tell us why you're a great fit for this role..."></textarea>
                <div class="form-text text-end">@_coverLetter.Length / 2000 characters</div>
            </div>
            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
            </div>
        </div>
    }

    <!-- Step 5: Review & Submit -->
    @if (_currentStep == 4)
    {
        <div class="step-content">
            <h2>Review & Submit</h2>

            <!-- Personal Info Review -->
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Personal Information</strong>
                    <a href="#" @onclick="() => GoToStep(0)" @onclick:preventDefault>Edit</a>
                </div>
                <div class="card-body">
                    <p><strong>Name:</strong> @_fullName</p>
                    <p><strong>Email:</strong> @_email</p>
                    <p><strong>Phone:</strong> @_phone</p>
                    <p><strong>Address:</strong> @_address</p>
                </div>
            </div>

            <!-- Work History Review -->
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Work History</strong>
                    <a href="#" @onclick="() => GoToStep(1)" @onclick:preventDefault>Edit</a>
                </div>
                <div class="card-body">
                    @foreach (var entry in _workEntries)
                    {
                        <div class="mb-3 pb-3 border-bottom">
                            <p><strong>@entry.Title</strong> at @entry.Company</p>
                            <p class="text-muted">
                                @entry.StartDate.ToString("MMM yyyy") —
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                            </p>
                            <p>@entry.Description</p>
                        </div>
                    }
                </div>
            </div>

            <!-- References Review -->
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>References</strong>
                    <a href="#" @onclick="() => GoToStep(2)" @onclick:preventDefault>Edit</a>
                </div>
                <div class="card-body">
                    @foreach (var reference in _references)
                    {
                        <div class="mb-2">
                            <p><strong>@reference.Name</strong> (@reference.Relationship)</p>
                            <p class="text-muted">@reference.Email | @reference.Phone</p>
                        </div>
                    }
                </div>
            </div>

            <!-- Cover Letter Review -->
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Cover Letter</strong>
                    <a href="#" @onclick="() => GoToStep(3)" @onclick:preventDefault>Edit</a>
                </div>
                <div class="card-body">
                    <p style="white-space: pre-wrap;">@_coverLetter</p>
                </div>
            </div>

            <div class="step-buttons">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                    @if (_isSubmitting)
                    {
                        <span>Submitting...</span>
                    }
                    else
                    {
                        <span>Submit Application</span>
                    }
                </button>
            </div>
        </div>
    }
}

<style>
